INSERT INTO simulator.question_versions(id,question_id,version,section,task_type,status,content) VALUES ('10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001',1,'READING','COMPLETE_THE_WORDS','APPROVED','{"taskType": "COMPLETE_THE_WORDS", "title": "A campus library", "instructions": "Complete each word by typing only the missing letters.", "segments": [{"text": "Students can "}, {"gapId": "g1", "prefix": "bor", "suffix": "", "missingLength": 3}, {"text": " books from the campus library. They must "}, {"gapId": "g2", "prefix": "re", "suffix": "", "missingLength": 4}, {"text": " them within two weeks."}]}'::jsonb);
INSERT INTO simulator.answer_keys(question_version_id,answers,explanation) VALUES ('10000000-0000-0000-0000-000000000001','{"g1": "row", "g2": "turn"}'::jsonb,'Borrow means take something temporarily. Return means give it back. The complete words are borrow and return.');
INSERT INTO simulator.question_versions(id,question_id,version,section,task_type,status,content) VALUES ('10000000-0000-0000-0000-000000000002','20000000-0000-0000-0000-000000000002',1,'READING','READ_IN_DAILY_LIFE','APPROVED','{"taskType": "READ_IN_DAILY_LIFE", "title": "A workshop notice", "instructions": "Read the notice and choose one answer.", "passage": "Campus bicycle workshop: On Friday, the repair desk will move from the courtyard to Room 12 because rain is expected. Opening hours remain 2\u20135 p.m. Students should bring their own bicycles; basic tools will be provided.", "prompt": "What will change on Friday?", "options": [{"id": "a", "text": "The location of the repair desk."}, {"id": "b", "text": "The opening hours of the workshop."}, {"id": "c", "text": "The requirement to bring a bicycle."}]}'::jsonb);
INSERT INTO simulator.answer_keys(question_version_id,answers,explanation) VALUES ('10000000-0000-0000-0000-000000000002','{"choice": "a"}'::jsonb,'The notice explicitly moves the desk to Room 12. Hours remain unchanged and students still bring their bicycles.');
INSERT INTO simulator.question_versions(id,question_id,version,section,task_type,status,content) VALUES ('10000000-0000-0000-0000-000000000003','20000000-0000-0000-0000-000000000003',1,'READING','READ_AN_ACADEMIC_PASSAGE','APPROVED','{"taskType": "READ_AN_ACADEMIC_PASSAGE", "title": "Urban trees and temperature", "instructions": "Read the passage and choose one answer.", "passage": "Urban trees can reduce local temperatures in two ways. Their leaves block some sunlight from reaching paved surfaces. In addition, water evaporating from leaves transfers heat away from the surrounding air. These effects depend on the size of the canopy and the availability of water. A small tree in dry soil may therefore provide less cooling than a large, well-watered tree, even when both grow on the same street.", "prompt": "According to the passage, why might two trees on the same street provide different amounts of cooling?", "options": [{"id": "a", "text": "Only one of them can block sunlight."}, {"id": "b", "text": "Their canopy sizes and access to water may differ."}, {"id": "c", "text": "Water evaporation always warms the surrounding air."}]}'::jsonb);
INSERT INTO simulator.answer_keys(question_version_id,answers,explanation) VALUES ('10000000-0000-0000-0000-000000000003','{"choice": "b"}'::jsonb,'The passage identifies canopy size and water availability as factors controlling cooling. Both mechanisms can operate in either tree; evaporation removes heat rather than warming the air.');
INSERT INTO simulator.blueprint_versions(id,name,version,duration_seconds,verification_status,question_version_ids) VALUES ('30000000-0000-0000-0000-000000000001','Reading practice',1,0,'CUSTOM_PRACTICE','["10000000-0000-0000-0000-000000000001", "10000000-0000-0000-0000-000000000002", "10000000-0000-0000-0000-000000000003"]'::jsonb);
